for (const [label, rows] of [["minus duplicate copy", dupRows], ["minus no activity for over 60 days", zombieRows]])
  for (const d of [...rows].sort((a, b) => weighted(b) - weighted(a))) {
    run -= weighted(d);
    bridgeRows.push({step: label, record_id: d["Record ID"], deal: d["Deal Name"], owner: ownerOf(d), stage: d["Deal Stage"], amount: d["Amount"], weighted: halfUp(weighted(d)), running_total: halfUp(run)});
  }
bridgeRows.push({step: "Q4 weighted forecast, cleaned", record_id: "", deal: "", owner: "", stage: "", amount: "", weighted: "", running_total: halfUp(cleaned)});
for (const d of noAmount) bridgeRows.push({step: "not counted: no amount", record_id: d["Record ID"], deal: d["Deal Name"], owner: ownerOf(d), stage: d["Deal Stage"], amount: "", weighted: "", running_total: ""});

const perOwner = {}; for (const [d] of flags) perOwner[ownerOf(d)] = (perOwner[ownerOf(d)] || 0) + 1;
const top = rows => [...rows].sort((a, b) => weighted(b) - weighted(a)).slice(0, 3).map(d => ({deal: d["Deal Name"], owner: ownerOf(d), weighted: eur(weighted(d))}));
const D = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"], M = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const nd = new Date(today * 86400000);
const facts = {
  date: `${D[nd.getUTCDay()]} ${nd.getUTCDate()} ${M[nd.getUTCMonth()]} ${nd.getUTCFullYear()}`,
  q4_forecast_as_exported: eur(raw), q4_forecast_cleaned: eur(cleaned), difference: eur(raw - cleaned),
  difference_pct_of_exported: `${halfUp(100 * (raw - cleaned) / raw, 1).toFixed(1)}%`,
  q4_open_deals: q4.length,
  removed_duplicate_copies: {deals: dupRows.length, weighted: eur(sum(dupRows)), largest: top(dupRows)},
  removed_no_activity_over_60_days: {deals: zombieRows.length, weighted: eur(sum(zombieRows)), largest: top(zombieRows)},
  not_counted_no_amount: {deals: noAmount.length, names: noAmount.map(d => d["Deal Name"]),
    meaning: "These count as zero in both figures, so once their amounts are filled in, the cleaned figure can only go up."},
  fix_this_week: Object.entries(perOwner).sort((a, b) => b[1] - a[1] || cmp(a[0], b[0])).map(([owner, items]) => ({owner, items})),
  items_total: flags.length,
  duplicate_pairs_for_a_person: verdicts.filter(v => v.verdict === "UNSURE").length,
};
// one to-do message per owner
const byOwner = {}; for (const [d, code] of flags) (byOwner[ownerOf(d)] = byOwner[ownerOf(d)] || []).push([d, code]);
const ownerMessages = facts.fix_this_week.map(({owner}) => {
  const items = byOwner[owner];
  const hi = owner === "(no owner)" ? "These deals have no owner. Please assign them:"
    : `Hi ${owner.split(" ")[0]}, ${items.length} things in HubSpot need you before this week's forecast call:`;
  return {to: owner === "(no owner)" ? "Head of RevOps (deals with no owner)" : owner, items: items.length,
          message: [hi, ...items.map(([d, code]) => `- ${d["Deal Name"]}: ${ACTION[code]}`)].join("\n")};
});
const notePrompt = $('Note prompt text').first().json.text.replace("{facts_json}", JSON.stringify(facts, null, 2));
return [{json: {facts, fixRows, reviewRows, bridgeRows, ownerMessages, notePrompt,
  summary: {q4_raw: halfUp(raw), q4_cleaned: halfUp(cleaned), flags: flags.length}}}];

const mode = $('Settings').first().json.aiMode;
if (mode === "off") return [{json: {draft: "", source: "off"}}];
return [{json: {draft: ($('Recorded note text').first().json.text || "").trim(), source: "AI (recorded)"}}];

const norm = n => n.replace(/\.+$/, "").replace(/,/g, "");
const numbersIn = t => new Set((t.match(/\d[\d,.]*\d|\d/g) || []).map(norm));
const moneyIn = t => [...t.matchAll(/€\s?(\d[\d,.]*\d|\d)/g)].map(m => norm(m[1]));
const pctIn = t => [...t.matchAll(/(\d[\d,.]*\d|\d)\s?%/g)].map(m => norm(m[1]));
// Python's json.dumps(ensure_ascii=False) and JSON.stringify give the same numbers, so the guard sees the same facts
function numberGuard(note, facts) {
  const factText = JSON.stringify(facts, null, 1);
  const allowed = numbersIn(factText); allowed.add("4");  // "Q4" is allowed
  const money = new Set(moneyIn(factText)), pct = new Set(pctIn(factText));
  const bad = new Set([...numbersIn(note)].filter(n => !allowed.has(n)));
  for (const m of moneyIn(note)) if (!money.has(m)) bad.add("€" + m);
  for (const m of pctIn(note)) if (!pct.has(m)) bad.add(m + "%");
  return [...bad].sort();
}
const r = $('3. Clean the Q4 forecast').first().json;
const f = r.facts, settings = $('Settings').first().json;
const draft = $input.first().json.draft, aiSource = $input.first().json.source;
let note = null, source = "template", problems = [];
if (draft) {
  problems = numberGuard(draft, f);
  if (problems.length) source = "template (AI draft failed the number guard)";
  else { note = draft; source = aiSource; }
}
if (note === null) note = [`Pipeline hygiene, ${f.date}`,
  `Q4 weighted forecast: ${f.q4_forecast_as_exported} as exported, ${f.q4_forecast_cleaned} after cleaning (${f.difference} less, ${f.difference_pct_of_exported}).`,
  `- Duplicate copies removed: ${f.removed_duplicate_copies.deals} deals, ${f.removed_duplicate_copies.weighted}.`,
  `- No activity for over 60 days, removed: ${f.removed_no_activity_over_60_days.deals} deals, ${f.removed_no_activity_over_60_days.weighted}.`,
  `- Not counted because the amount is empty: ${f.not_counted_no_amount.deals} deals.`,
  "Fix this week: " + f.fix_this_week.map(o => `${o.owner} ${o.items}`).join(", ") + ".",
  `Duplicate pairs a person needs to decide: ${f.duplicate_pairs_for_a_person}.`].join("\n");
const guardText = `note used: ${source}\nnumbers in the AI draft not found in facts.json: ${problems.length ? problems.join(", ") : "none"}\n`;
const wouldSend = [
  {logged_at: settings.now, channel: "#sales-leadership (would post, nothing sent)", what: "Monday pipeline hygiene note", file: "4-monday-note.md", note_source: source},
  {logged_at: settings.now, channel: "direct messages (would send, nothing sent)", what: `${r.ownerMessages.length} owner to-do messages`, file: "6-owner-messages.csv", note_source: "template"}];
return [{json: {...r, note: note + "\n", guardText, wouldSend, noteSource: source}}];
